// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/pms/categories", wrapper.ListCategories)
	router.POST(options.BaseURL+"/pms/categories", wrapper.CreateCategory)
	router.DELETE(options.BaseURL+"/pms/categories/:id", wrapper.DeleteCategory)
	router.PATCH(options.BaseURL+"/pms/categories/:id", wrapper.UpdateCategory)
	router.GET(options.BaseURL+"/pms/products", wrapper.ListProducts)
	router.POST(options.BaseURL+"/pms/products", wrapper.CreateProduct)
	router.DELETE(options.BaseURL+"/pms/products/:id", wrapper.DeleteProduct)
	router.GET(options.BaseURL+"/pms/products/:id", wrapper.GetProduct)
	router.PATCH(options.BaseURL+"/pms/products/:id", wrapper.UpdateProduct)
	router.PUT(options.BaseURL+"/pms/products/:id/translations", wrapper.SetProductTranslations)
	router.POST(options.BaseURL+"/pms/products/:id/merge-preview", wrapper.PreviewProductMerge)
	router.POST(options.BaseURL+"/pms/products/:id/merge", wrapper.MergeProduct)
	router.POST(options.BaseURL+"/pms/products/:id/duplicate", wrapper.DuplicateProduct)
	router.GET(options.BaseURL+"/pms/products/:id/media", wrapper.ListProductMedia)
	router.POST(options.BaseURL+"/pms/products/:id/media", wrapper.UploadProductMedia)
	router.DELETE(options.BaseURL+"/pms/media/:id", wrapper.DeleteMedia)
	router.PATCH(options.BaseURL+"/pms/media/:id", wrapper.UpdateMedia)
	router.POST(options.BaseURL+"/pms/products/:id/variants", wrapper.CreateVariant)
	router.DELETE(options.BaseURL+"/pms/variants/:id", wrapper.DeleteVariant)
	router.PATCH(options.BaseURL+"/pms/variants/:id", wrapper.UpdateVariant)
	router.POST(options.BaseURL+"/pms/variants/:id/skus", wrapper.CreateSKU)
	router.GET(options.BaseURL+"/pms/skus/barcode-lookup/:code", wrapper.ResolveBarcode)
	router.DELETE(options.BaseURL+"/pms/skus/:id", wrapper.DeleteSKU)
	router.PATCH(options.BaseURL+"/pms/skus/:id", wrapper.UpdateSKU)
	router.GET(options.BaseURL+"/pms/skus/:id/margin-insight", wrapper.GetSKUMarginInsight)
	router.DELETE(options.BaseURL+"/pms/skus/:id/cost-price", wrapper.ClearCostPriceOverride)
	router.PUT(options.BaseURL+"/pms/skus/:id/cost-price", wrapper.SetManualCostPrice)
	router.POST(options.BaseURL+"/pms/skus/:id/cost-price/correction", wrapper.CorrectCost)
	router.GET(options.BaseURL+"/pms/skus/:id/cost-price-history", wrapper.ListSKUCostPriceHistory)
	router.GET(options.BaseURL+"/pms/skus/:id/price-history", wrapper.ListSKUPriceHistory)
	router.GET(options.BaseURL+"/pms/skus/:id/currency-prices", wrapper.ListSKUCurrencyPrices)
	router.PUT(options.BaseURL+"/pms/skus/:id/currency-prices", wrapper.UpsertSKUCurrencyPrice)
	router.DELETE(options.BaseURL+"/pms/skus/:id/currency-prices/:currencyCode", wrapper.DeleteSKUCurrencyPrice)
	router.GET(options.BaseURL+"/pms/skus/:id/barcode-aliases", wrapper.ListBarcodeAliases)
	router.POST(options.BaseURL+"/pms/skus/:id/barcode-aliases", wrapper.CreateBarcodeAlias)
	router.DELETE(options.BaseURL+"/pms/barcode-aliases/:id", wrapper.DeleteBarcodeAlias)
	router.GET(options.BaseURL+"/pms/skus/:id/scale-code-aliases", wrapper.ListScaleCodeAliases)
	router.POST(options.BaseURL+"/pms/skus/:id/scale-code-aliases", wrapper.CreateScaleCodeAlias)
	router.DELETE(options.BaseURL+"/pms/scale-code-aliases/:id", wrapper.DeleteScaleCodeAlias)
	router.GET(options.BaseURL+"/pms/products/:id/history", wrapper.ListProductHistory)
	router.GET(options.BaseURL+"/pms/variants/:id/history", wrapper.ListVariantHistory)
	router.GET(options.BaseURL+"/pms/margin-report", wrapper.ListMarginReport)
}

